//! The SP7 defaults that follow both donors' PCD databases, checked against
//! the decision table of the venice research (`reports/research/VALUES/
//! decisions.json`, generated by `tools/values/decisions.py` from the Dell
//! PR9XJ 1.0.8 and GIGABYTE MD25-CG0 F01 images).
//!
//! The rows are mirrored in [`ROWS`] (decision, Dell, GIGABYTE, as the JSON
//! spells them), so the test runs without the research tree. With
//! `FSTART_VENICE_DECISIONS` naming the JSON, the mirror is first checked
//! against it.

use fstart_driver_amd::ccx::{pm::Wdt, wh as ccx_wh};
use fstart_driver_amd::dxio::wh::{GlobalConfig, straps};
use fstart_driver_amd::nbio::wh::{self as nbio_wh, init::aer_mechanism};
use fstart_driver_amd::smu::v14::init as smu_init;

/// `(decision, dell, gbt)`: the agreeing rows fstart adopts, and the
/// differing ones whose SoC default is documented.
const ROWS: &[(&str, &str, &str)] = &[
    ("C-state I/O base (in[0x1d], C001_0073)", "0x413", "0x413"),
    ("C-state mode (in[0x1b])", "0x1", "0x1"),
    ("CC6 (in[0x1c])", "0x1", "0x1"),
    ("CPU WDT enable (in[0x13])", "0x1", "0x1"),
    ("CPU WDT severity (in[0x1a])", "0xff", "0xff"),
    ("L1 stream prefetcher (in[0xe..0x12])", "0x1", "0x1"),
    ("L1 stride prefetcher (in[0xe..0x12])", "0x1", "0x1"),
    ("L1 region prefetcher (in[0xe..0x12])", "0x1", "0x1"),
    ("L2 stream prefetcher (in[0xe..0x12])", "0x1", "0x1"),
    ("L2 up/down prefetcher (in[0xe..0x12])", "0x1", "0x1"),
    ("Core performance boost (in[0x1f])", "0x1", "0x1"),
    ("SVM enable / lock (in[0xb1]/[0xb2])", "0x1", "0x1"),
    ("SMEE (in[0x22])", "0x0", "0x0"),
    ("in[0xa5] (fstart: WC speculation)", "0xff", "0xff"),
    (
        "SMM lock: HWCR |= 0x8000_0001 (AmdCcxZen6Dxe/Pei)",
        "0x1",
        "0x1",
    ),
    (
        "RAS: PCD 0x1E1 (RAS property bit 1 / RAS_SYNC_FLOOD)",
        "0x1",
        "0x1",
    ),
    (
        "RAS: PCD 0x1E0 poison consumption (RAS bit 4)",
        "0x0",
        "0x0",
    ),
    ("RAS: PCD 0x18 environment flag", "0x0", "0x0"),
    ("AER enable: SMU msg 9 a0 (PCD 0x212)", "0x1", "0x1"),
    ("AER report mechanism: msg 9 a1 (PCD 0x1E6)", "0x2", "0x2"),
    ("TPH completer (cfg+0x09)", "0x1", "0x1"),
    ("SNP AVIC (cfg+0x1A, PcdCfgIommuAvicSupport)", "0x1", "0x1"),
    ("IOMMU (cfg+0x1F, PCD 0x223)", "0x1", "0x1"),
    ("SNP (cfg+0x51, PCD 0x23F)", "0x0", "0x0"),
    ("cfg+0x92 (fstart: EFR shadow bit 5)", "0x0", "0x0"),
    (
        "cfg+0x9D L2A C4/C8 (PcdCfgIommuErrReportingWA)",
        "0x0",
        "0x0",
    ),
    ("cfg+0x2A NBIF_OPT_2A (PcdCfgSriovEnDev0F1)", "0x1", "0x0"),
    ("cfg+0x90 NBIF_OPT_90 (PcdAmdFabricCdma)", "0x0", "0x0"),
    (
        "MPIO_ENABLE_CG (msg 5) a2: unused-tile CG (PCD 0x367)",
        "0x1",
        "None",
    ),
    ("IOAPIC ID of the FCH", "0x80", "0x80"),
    ("IOAPIC ID base of NBIO IOAPICs", "0xf0", "0xf0"),
    ("input +0x29 (MPIO straps 0x1D...)", "0x1", "0x1"),
    ("input +0x92", "0x0", "0x0"),
    ("input +0x9B", "0x1", "0x0"),
    ("input +0x9E", "0x7", "0x7"),
    ("input +0xA2 (Gen6 EQ mode)", "0xff", "0xff"),
    ("ReicResponseDisable (global dword 3 b23)", "0x0", "0x0"),
    ("HSMP interrupts msg 0x41 (PcdCfgHSMPSupport)", "0x1", "0x1"),
    ("Boost Fmax msg 0x2B (PcdAmdBoostFmax)", "0x0", "0x0"),
    ("EDC excursion msg 0x4A", "0x0", "0x0"),
    ("PPTable TDC SOC (A)", "0x136", "0x136"),
    ("PPTable TDC MEM/VDDIO (A)", "0xd2", "0xd2"),
    ("Sync flood: reset CPU (SMU 0x3B)", "0x1", "0x0"),
    ("Sync flood: delay (SMU 0x4D)", "0x5", "0x0"),
    (
        "PSP LockFCHReg 0x30 at SMM ReadyToBoot (PcdFchOemSecureEnable)",
        "0x1",
        "0x1",
    ),
    ("PSP LockGpio 0x3A (PcdFchOemGpioFencing)", "0x0", "0x0"),
];

/// The donors' value of `decision` as a number (`None` for "None").
fn donors(decision: &str) -> (Option<u64>, Option<u64>) {
    let (_, dell, gbt) = ROWS
        .iter()
        .find(|row| row.0 == decision)
        .unwrap_or_else(|| panic!("no row {decision}"));
    let num = |s: &str| u64::from_str_radix(s.strip_prefix("0x")?, 16).ok();
    (num(dell), num(gbt))
}

/// Both donors' value of an agreeing row.
fn agreed(decision: &str) -> u64 {
    let (dell, gbt) = donors(decision);
    assert_eq!(dell, gbt, "{decision}: the donors differ");
    dell.unwrap()
}

#[test]
fn the_mirror_is_the_research_table() {
    let Ok(path) = std::env::var("FSTART_VENICE_DECISIONS") else {
        return;
    };
    let text = std::fs::read_to_string(&path).expect("decisions.json");
    let rows: serde_json::Value = serde_json::from_str(&text).expect("JSON");
    let rows = rows.as_array().expect("an array");
    for (decision, dell, gbt) in ROWS {
        let row = rows
            .iter()
            .find(|r| r["decision"] == *decision)
            .unwrap_or_else(|| panic!("{decision} not in {path}"));
        // JSON `null` is the mirror's "None".
        let text = |v: &serde_json::Value| v.as_str().unwrap_or("None").to_owned();
        assert_eq!(text(&row["dell"]), *dell, "{decision}");
        assert_eq!(text(&row["gbt"]), *gbt, "{decision}");
    }
}

#[test]
fn ccx_defaults_are_the_donors() {
    let p = ccx_wh::Policy::default();
    let b = |on: bool| u64::from(on);
    assert_eq!(
        u64::from(p.cstate_io_base),
        agreed("C-state I/O base (in[0x1d], C001_0073)")
    );
    assert_eq!(b(p.cstates), agreed("C-state mode (in[0x1b])"));
    assert_eq!(b(p.cc6), agreed("CC6 (in[0x1c])"));
    assert_eq!(b(p.wdt.is_some()), agreed("CPU WDT enable (in[0x13])"));
    // PcdAmdCpuWdtTimeout 0xFFFF becomes in[0x18] = 0x100: TimeBase in
    // the low byte, CountSel in the high byte.
    let wdt = p.wdt.unwrap();
    assert_eq!(wdt, Wdt::DEFAULT);
    assert_eq!(
        u16::from(wdt.time_base) | u16::from(wdt.count_sel) << 8,
        0x100
    );
    assert_eq!(p.wdt_severity, None);
    assert_eq!(0xff, agreed("CPU WDT severity (in[0x1a])"), "0xFF = keep");
    for (disabled, row) in [
        (p.disable_l1_stream, "L1 stream prefetcher (in[0xe..0x12])"),
        (p.disable_l1_stride, "L1 stride prefetcher (in[0xe..0x12])"),
        (p.disable_l1_region, "L1 region prefetcher (in[0xe..0x12])"),
        (p.disable_l2_stream, "L2 stream prefetcher (in[0xe..0x12])"),
        (
            p.disable_l2_up_down,
            "L2 up/down prefetcher (in[0xe..0x12])",
        ),
    ] {
        assert_eq!(b(!disabled), agreed(row), "{row}");
    }
    assert_eq!(b(p.boost), agreed("Core performance boost (in[0x1f])"));
    assert_eq!(
        b(p.svm && p.svm_lock),
        agreed("SVM enable / lock (in[0xb1]/[0xb2])")
    );
    assert_eq!(b(p.smee), agreed("SMEE (in[0x22])"));
    // in[0xa5] = 0xFF: the consumer writes nothing.
    assert_eq!(agreed("in[0xa5] (fstart: WC speculation)"), 0xff);
    assert_eq!(p.wc_spec, None);
    // PcdAmdSmmLock 1: HWCR |= 0x8000_0001 (sp7's SMM SetupBits).
    use fstart_arch::x86::cpu::amd::msr::Hwcr;
    assert_eq!(
        agreed("SMM lock: HWCR |= 0x8000_0001 (AmdCcxZen6Dxe/Pei)"),
        1
    );
    assert_eq!(
        Hwcr::LOCK_31::SET.value | Hwcr::SMM_LOCK::SET.value,
        0x8000_0001
    );
}

#[test]
fn nbio_defaults_are_the_donors() {
    let p = nbio_wh::Policy::default();
    let b = |on: bool| u64::from(on);
    assert_eq!(
        u64::from(p.ras.pcd_1e1),
        agreed("RAS: PCD 0x1E1 (RAS property bit 1 / RAS_SYNC_FLOOD)")
    );
    assert_eq!(
        b(p.ras.pcd_1e0),
        agreed("RAS: PCD 0x1E0 poison consumption (RAS bit 4)")
    );
    assert_eq!(b(p.ras.pcd_18), agreed("RAS: PCD 0x18 environment flag"));
    assert_eq!(b(p.aer), agreed("AER enable: SMU msg 9 a0 (PCD 0x212)"));
    // Both donors are firmware-first, and so is fstart
    // (`nbio::wh::Policy::aer_mechanism`, `smm::aer`).
    assert_eq!(
        agreed("AER report mechanism: msg 9 a1 (PCD 0x1E6)"),
        u64::from(aer_mechanism::FIRMWARE_FIRST)
    );
    assert_eq!(p.aer_mechanism, aer_mechanism::FIRMWARE_FIRST);
    assert_eq!(b(p.tph_completer), agreed("TPH completer (cfg+0x09)"));
    assert_eq!(
        u64::from(p.snp_avic),
        agreed("SNP AVIC (cfg+0x1A, PcdCfgIommuAvicSupport)")
    );
    assert_eq!(b(p.iommu), agreed("IOMMU (cfg+0x1F, PCD 0x223)"));
    assert_eq!(b(p.snp), agreed("SNP (cfg+0x51, PCD 0x23F)"));
    assert_eq!(
        b(p.iommu_efr_bit5),
        agreed("cfg+0x92 (fstart: EFR shadow bit 5)")
    );
    assert_eq!(
        b(p.iommu_l2a_c4),
        agreed("cfg+0x9D L2A C4/C8 (PcdCfgIommuErrReportingWA)")
    );
    assert_eq!(
        b(p.nbif.opt_90),
        agreed("cfg+0x90 NBIF_OPT_90 (PcdAmdFabricCdma)")
    );
    // Donors differ: the SoC default is Dell's.
    let (dell, _) = donors("cfg+0x2A NBIF_OPT_2A (PcdCfgSriovEnDev0F1)");
    assert_eq!(Some(b(p.nbif.features)), dell);
    let (dell, gbt) = donors("MPIO_ENABLE_CG (msg 5) a2: unused-tile CG (PCD 0x367)");
    assert_eq!((Some(b(p.unused_tile_clock_gating)), gbt), (dell, None));
    assert_eq!(
        u64::from(super::FCH_IOAPIC_ID),
        agreed("IOAPIC ID of the FCH")
    );
    assert_eq!(
        u64::from(super::IOAPIC_ID_BASE),
        agreed("IOAPIC ID base of NBIO IOAPICs")
    );
}

#[test]
fn mpio_defaults_are_the_donors() {
    let s = straps::Policy::default();
    let b = |on: bool| u64::from(on);
    assert_eq!(
        b(s.rx_margin_persistence),
        agreed("input +0x29 (MPIO straps 0x1D...)")
    );
    assert_eq!(b(s.sev_tio), agreed("input +0x92"));
    assert_eq!(u64::from(s.defer_rx_standby), agreed("input +0x9E"));
    assert_eq!(
        u64::from(s.gen6_eq_mode),
        agreed("input +0xA2 (Gen6 EQ mode)")
    );
    // PcdPtmEn: the donors differ, Dell's is the default.
    assert_eq!(Some(b(s.ptm)), donors("input +0x9B").0);
    assert_eq!(
        b(GlobalConfig::DEFAULT.reic_response_disable),
        agreed("ReicResponseDisable (global dword 3 b23)")
    );
}

#[test]
fn smu_defaults_are_the_donors() {
    let p = smu_init::Policy::DEFAULT;
    let b = |on: bool| u64::from(on);
    assert_eq!(
        b(p.hsmp),
        agreed("HSMP interrupts msg 0x41 (PcdCfgHSMPSupport)")
    );
    assert_eq!(
        u64::from(p.boost_fmax_mhz),
        agreed("Boost Fmax msg 0x2B (PcdAmdBoostFmax)")
    );
    assert_eq!(
        b(p.edc_excursion_reporting.is_some()),
        agreed("EDC excursion msg 0x4A")
    );
    // The platform limits are board data: fused by default. TDC SoC and
    // VDDIO agree in both donors but are platform limits too.
    let t = &p.pptable;
    assert_eq!(t.tdc_soc_platform_limit.get(), 0);
    assert_eq!(t.tdc_vddio_mem_s3_platform_limit.get(), 0);
    // Both donors' boards set 310 A and 210 A (the MD25's are in its
    // crate, `POWER_LIMITS`).
    assert_eq!(agreed("PPTable TDC SOC (A)"), 310);
    assert_eq!(agreed("PPTable TDC MEM/VDDIO (A)"), 210);
}

#[test]
fn fch_defaults_and_differences() {
    // The sync flood differs (Dell reset after 5, GIGABYTE none): the SoC
    // default is openSIL's, a board names its own.
    assert_eq!(
        donors("Sync flood: reset CPU (SMU 0x3B)"),
        (Some(1), Some(0))
    );
    assert_eq!(donors("Sync flood: delay (SMU 0x4D)"), (Some(5), Some(0)));
    const { assert!(super::SYNC_FLOOD.reset_cpu && super::SYNC_FLOOD.delay == 0) };
    // LockFCHReg is sent from SMM at ready-to-boot (`sp7::smm`), LockGpio
    // is not.
    assert_eq!(
        agreed("PSP LockFCHReg 0x30 at SMM ReadyToBoot (PcdFchOemSecureEnable)"),
        1
    );
    assert_eq!(agreed("PSP LockGpio 0x3A (PcdFchOemGpioFencing)"), 0);
    assert_eq!(
        super::smm::Report::NONE.fch_lock,
        crate::smm::status::NOT_SENT
    );
    // The ISA step drops every LPC decode and changes the SPI read clock
    // in both donors (eSPI boards): a board opts in, the SoC default runs
    // nothing (REVIEW2 P1-6).
    assert_eq!(super::Devices::default().isa, None);
}
